///|
fn diagnostic_add_protected(
  value : String,
  output : String,
  uncertain : Bool,
  destination : Array[String],
  result : DiagnosticProtectedValues,
) -> Unit {
  if value == "" ||
    (
      !output.contains(value) &&
      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
    ) {
    return
  }
  if result.secrets.length() >= 512 {
    result.incomplete = true
    return
