205	///|
206	async fn read_codex_auth(home : String) -> CodexAuth {
207	  guard @fs.file_size(home + "/auth.json") <= 65536L else {
208	    raise AdapterError("Invalid Codex auth size")
209	  }
210	  let source = @fs.read_file(home + "/auth.json")
211	  guard source.binary().length() <= 65536 else {
212	    raise AdapterError("Invalid Codex auth size")
213	  }
214	  let auth = @json.parse(source.text())
215	  guard (
216	      field(auth, "OPENAI_API_KEY") == None ||
217	      field(auth, "OPENAI_API_KEY") == Some(Json::null())
218	    ) &&
219	    (
220	      field(auth, "auth_mode") == None ||
221	      field(auth, "auth_mode") == Some(Json::string("chatgpt"))
222	    ) else {
223	    raise AdapterError("Unsupported Codex auth mode")
224	  }
225	  guard field(auth, "tokens") is Some(tokens) else {
226	    raise AdapterError("Missing Codex auth tokens")
227	  }
228	  let access = required(tokens, "access_token")
229	  let secrets = [access]
230	  for name in ["id_token", "refresh_token"] {
231	    if field(tokens, name) is Some(Json::String(value)) && value != "" {
232	      secrets.push(value)
233	    }
234	  }
235	  let segments = access.split(".").to_array()
236	  guard segments.length() == 3 else {
237	    raise AdapterError("Invalid access token")
238	  }
239	  let encoded = segments[1]
240	    .to_owned()
241	    .replace_all(old="-", new="+")
242	    .replace_all(old="_", new="/")
243	  let padding = (4 - encoded.length() % 4) % 4
244	  let claims = @json.parse(
245	    @utf8.decode(@base64.decode(encoded + "=".repeat(padding))),
246	  )
247	  guard field(claims, "exp") is Some(Json::Number(expiry, ..)) else {
248	    raise AdapterError("Invalid access token expiry")
249	  }
250	  { access, account: required(tokens, "account_id"), expiry, secrets, }
251	}
