294	///|
295	async fn refresh_codex(home : String, secrets : Array[String]) -> Unit {
296	  let (reader, output) = @process.read_from_process()
297	  defer reader.close()
298	  let (input, writer) = @process.write_to_process()
299	  defer writer.close()
300	  let (errors, stderr) = @process.read_from_process()
301	  defer errors.close()
302	  let captured = @buffer.Buffer(size_hint=1024)
303	  let incomplete : Ref[Bool] = { val: false, }
304	  let finished : Ref[Bool] = { val: false, }
305	  let failure = try {
306	    @async.with_task_group(async fn(group) {
307	      ignore(
308	        @process.spawn(
309	          group,
310	          "codex",
311	          ["app-server", "--stdio"],
312	          extra_env={ "CODEX_HOME": home },
313	          stdin=input,
314	          stdout=output,
315	          stderr~,
316	          no_wait=true,
317	        ),
318	      )
319	      group.spawn_bg(no_wait=true, async fn() {
320	        while errors.read_some(max_len=4096) is Some(chunk) {
321	          let remaining = 8192 - captured.length()
322	          let count = if chunk.length() < remaining {
323	            chunk.length()
324	          } else {
325	            remaining
326	          }
327	          if count > 0 {
328	            captured.write_bytes(chunk[:count])
329	          }
330	          if count < chunk.length() {
331	            incomplete.val = true
332	          }
333	        }
334	        finished.val = true
335	      })
336	      let initialize : Json = {
337	        "id": 1,
338	        "method": "initialize",
339	        "params": {
340	          "clientInfo": { "name": "orca-env-devsy", "version": version },
341	        },
342	      }
343	      writer.write(initialize.stringify() + "\n")
344	      codex_rpc_response(reader, 1, secrets)
345	      writer.write("{\"method\":\"initialized\"}\n")
346	      writer.write(
347	        "{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":true}}\n",
348	      )
349	      codex_rpc_response(reader, 2, secrets)
350	    })
351	    None
352	  } catch {
353	    error => Some(error)
354	  }
355	  if failure is Some(error) {
356	    if @async.is_being_cancelled() {
357	      raise error
358	    }
359	    let protected_input : Json = { "access_token": secrets }
360	    let detail = diagnostic_output(
361	      captured.to_bytes(),
362	      @env.get_env_vars(),
363	      protected_input=protected_input.stringify(),
364	      omitted=incomplete.val || !finished.val,
365	    )
366	    raise AdapterError(
367	      diagnostic_error(error) +
368	      detail
369	      .map(value => "\nCodex app-server stderr: " + value)
370	      .unwrap_or(
371	        if finished.val {
372	          ""
373	        } else {
374	          "\n[Codex app-server stderr incomplete]"
375	        },
376	      ),
377	    )
378	  }
379	}
