381	///|
382	async fn codex_credentials(home : String, recording~ : Bool) -> CodexAuth {
383	  let initial = read_codex_auth(home)
384	  if initial.expiry - @env.now().to_double() / 1000 >= 604800 {
385	    return initial
386	  }
387	  let lock = @fs.open(
388	    home + "/.orca-env-devsy-refresh.lock",
389	    mode=ReadWrite,
390	    create_mode=OpenOrCreate,
391	    permission=0o600,
392	  )
393	  defer lock.close()
394	  while !lock.try_lock(Exclusive) {
395	    @async.sleep(100)
396	  }
397	  let before = read_codex_auth(home)
398	  if before.expiry - @env.now().to_double() / 1000 >= 604800 {
399	    return before
400	  }
401	  let mut phase = "refresh"
402	  try {
403	    refresh_codex(home, before.secrets)
404	    phase = "verify"
405	    let after = read_codex_auth(home)
406	    guard after.access != before.access && after.expiry > before.expiry else {
407	      raise AdapterError("Codex refresh not persisted")
408	    }
409	    save_diagnostic("codex-refresh", "success", recording~)
410	  } catch {
411	    error => {
412	      progress_write(
413	        "orca-env-devsy: warning: Codex refresh failed; checking remaining token lifetime\n",
414	      )
415	      let detail = diagnostic_error(error)
416	      save_diagnostic(
417	        "codex-refresh",
418	        "warning",
419	        phase~,
420	        error_type=if error is @async.TimeoutError {
421	          "timeout"
422	        } else {
423	          "refresh_failed"
424	        },
425	        error_message=detail,
426	        recording~,
427	      )
428	    }
429	  }
430	  let current = read_codex_auth(home)
431	  guard current.expiry > @env.now().to_double() / 1000 else {
432	    raise AdapterError("Expired access token")
433	  }
434	  if current.expiry - @env.now().to_double() / 1000 < 604800 {
435	    progress_write(
436	      "orca-env-devsy: warning: Codex token has less than seven days remaining\n",
437	    )
438	  }
439	  current
440	}

