232	    cwd?=workspace_directory(state).map(path => path[:]),
233	  )
234	  let mut output = raw_output
235	  if recording {
236	    let mut observed = None
237	    let mut truncated = Json::array([])
238	    let mut observation_error = false
239	    if raw_output.split_once("\n") is Some((first, remaining)) {
240	      let event = @json.parse(first.to_owned()) catch { _ => Json::null() }
241	      if field(event, "kind") == Some(Json::string("result")) &&
242	        field(event, "serverEnvironment") is Some(value) {
243	        observed = Some(value)
244	        truncated = field(event, "truncated").unwrap_or(Json::array([]))
245	        observation_error = field(event, "observationError") ==
246	          Some(Json::boolean(true))
247	        output = remaining.to_owned()
