101	async fn settings_process(
102	  program : String,
103	  args : Array[String],
104	  environment~ : Map[String, String],
105	  input? : String,
106	  protected_secrets? : Array[String],
107	  protection_incomplete~ : Bool = false,
108	) -> String {
109	  let (stdin, writer) = @process.write_to_process()
110	  defer writer.close()
111	  @async.with_task_group(async fn(group) {
112	    let output = group.spawn(async fn() {
113	      diagnostic_process_output(
114	        program,
115	        args,
116	        environment~,
117	        stdin~,
118	        stdout_limit=4194304,
119	        stderr_limit=8192,
120	      )
121	    })
122	    let write_error = try {
123	      if input is Some(value) {
124	        writer.write(value)
125	      }
126	      None
127	    } catch {
128	      error =>
129	        if @async.is_being_cancelled() {
130	          raise error
131	        } else {
132	          Some(error)
133	        }
134	    }
135	    writer.close()
136	    let (status, stdout, stdout_truncated, stderr, stderr_truncated) = if write_error
137	      is Some(error) {
138	      @async.with_timeout(1000, async fn() { output.wait() }) catch {
139	        wait_error => {
140	          if @async.is_being_cancelled() {
141	            raise wait_error
142	          }
143	          raise AdapterError(
144	            "Orca settings input transfer failed; process exit unavailable: " +
145	            diagnostic_error(error, environment~),
146	          )
147	        }
148	      }
149	    } else {
150	      output.wait()
151	    }
152	    guard status == 0 else {
153	      let mut phase = "process"
154	      let mut code = "process_exit"
155	      let mut detail = if protection_incomplete {
156	        Some(
157	          "error detail unavailable because workspace protection values could not be read\n[error details incomplete or truncated]",
158	        )
159	      } else {
160	        diagnostic_output(
161	          stderr,
162	          environment,
163	          protected_input?=input,
164	          protect_all_input=true,
165	          protected_secrets?,
166	          omitted=stderr_truncated,
167	        )
168	      }
169	      if !stderr_truncated && !protection_incomplete {
170	        try {
171	          let error = @json.parse(@utf8.decode(stderr))
172	          let reported_phase = required(error, "phase")
173	          let reported_code = required(error, "code")
174	          if [
175	              "load", "read", "normalize", "input", "profile", "write", "verify",
176	            ].contains(reported_phase) &&
177	            ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
178	              reported_code,
179	            ) {
180	            phase = reported_phase
181	            code = reported_code
182	            let kind = match field(error, "kind") {
183	              Some(Json::String(value)) if [
184	                  "Error", "TypeError", "SyntaxError", "ReferenceError", "RangeError",
185	                  "AssertionError", "URIError",
186	                ].contains(value) => Some(value)
187	              _ => None
188	            }
189	            let native_code = match field(error, "nativeCode") {
190	              Some(Json::String(value)) if value.length() > 0 &&
191	                value.length() <= 64 &&
192	                value
193	                .iter()
194	                .all(c => {
195	                  (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
196	                }) => Some(value)
197	              _ => None
198	            }
199	            detail = if kind is Some(kind) {
200	              Some(
201	                kind +
202	                native_code.map(value => " (" + value + ")").unwrap_or(""),
203	              )
204	            } else {
205	              None
206	            }
207	            for
208	              name in (if native_code == Some("MODULE_NOT_FOUND") {
209	                ["target", "missing", "cause", "location", "message", "path"]
210	              } else {
211	                ["target", "cause", "location", "message", "path"]
212	              }) {
213	              if field(error, name) is Some(Json::String(value)) &&
214	                value.length() > 0 &&
215	                value.length() <= 1024 &&
216	                diagnostic_output(
217	                  @utf8.encode(value),
218	                  environment,
219	                  protected_input?=input,
220	                  protect_all_input=true,
221	                  protected_secrets?,
222	                  omitted=field(error, "detailsTruncated") ==
223	                    Some(Json::boolean(true)) &&
224	                    (name == "message" || name == "path" || name == "missing"),
225	                )
226	                is Some(safe) {
227	                detail = Some(
228	                  detail.unwrap_or("Error") + " " + name + "=" + safe,
229	                )
230	              }
231	            }
232	            if field(error, "detailsTruncated") == Some(Json::boolean(true)) {
233	              detail = Some(
234	                detail.unwrap_or("Error") +
235	                "\n[error details incomplete or truncated]",
236	              )
237	            }
238	          }
239	        } catch {
240	          _ => ()
241	        }
242	      }
243	      if write_error is Some(error) {
244	        detail = Some(
245	          detail.unwrap_or("Process exited without readable stderr") +
246	          "\nInput transfer failed: " +
247	          diagnostic_error(error, environment~),
248	        )
249	      }
250	      if stdout_truncated {
251	        detail = Some(incomplete_diagnostic_detail(detail))
252	      }
253	      raise SettingsProcessError(phase, code, status, detail)
254	    }
255	    if write_error is Some(error) {
256	      raise error
257	    }
258	    guard !stdout_truncated else {
259	      raise AdapterError("Orca settings result exceeds size limit")
260	    }
261	    @utf8.decode(stdout)
262	  })
263	}
