207	///|
208	fn terminal_text(text : String) -> String? {
209	  let output = @buffer.Buffer(size_hint=256)
210	  let mut state = 0
211	  for c in text.iter() {
212	    match state {
213	      0 =>
214	        if c == '\u001b' {
215	          state = 1
216	        } else if c.to_int() < 32 && c != '\t' {
217	          return None
218	        } else {
219	          output.write_char_utf8(c)
220	        }
221	      1 =>
222	        if c == '[' {
223	          state = 2
224	        } else if c == ']' {
225	          state = 3
226	        } else {
227	          return None
228	        }
229	      2 => if c >= '@' && c <= '~' { state = 0 }
230	      3 => if c == '\u0007' { state = 0 } else if c == '\u001b' { state = 4 }
231	      _ => if c == '\\' { state = 0 } else { state = 3 }
232	    }
233	  }
234	  if state != 0 {
235	    None
236	  } else {
237	    Some(@utf8.decode_lossy(output.to_bytes()))
238	  }
239	}
