450	///|
451	async fn Progress::line(
452	  self : Progress,
453	  line : String,
454	  statuses~ : Bool,
455	  messages~ : Bool,
456	) -> Unit {
457	  if line.trim() == "" {
458	    return
459	  }
460	  let event = @json.parse(line) catch { _ => Json::null() }
461	  if event != Json::null() {
462	    let protected_values : DiagnosticProtectedValues = {
463	      secrets: [],
464	      visited: 0,
465	      incomplete: false,
466	    }
467	    diagnostic_protected_values(event, protected_values, line, false)
468	    if protected_values.incomplete ||
469	      self.secrets.length() + protected_values.secrets.length() > 1024 {
470	      self.protection_incomplete = true
471	      self.details_truncated = true
472	    } else {
473	      for secret in protected_values.secrets {
474	        add_protected_secret(self.secrets, secret)
475	      }
476	      self.secrets.sort_by((a, b) => b.length().compare(a.length()))
477	    }
478	  }
479	  if field(event, "kind") == Some(Json::string("status")) {
480	    if field(event, "state") == Some(Json::string("failed")) &&
481	      field(event, "error") is Some(error) {
482	      let mut described = false
483	      for name in ["message", "hint"] {
484	        if field(error, name) is Some(Json::String(text)) {
485	          described = true
486	          self.message(
487	            text,
488	            debug=false,
489	            warning=true,
490	            emit=messages || statuses,
491	          )
492	        }
493	      }
494	      if !described {
495	        self.remember_unrecognized_json(event)
496	      }
497	    }
498	    if statuses || messages {
499	      self.status(event)
500	    }
501	    return
502	  }
503	  // Result envelopes and arbitrary structured responses are never log text.
504	  if field(event, "kind") == Some(Json::string("result")) ||
505	    field(event, "kind") == Some(Json::string("orca-env-devsy-server-exit")) {
506	    return
507	  }
508	  if event is Json::Object(_) {
509	    let kind = field(event, "kind")
510	    guard kind == None ||
511	      kind == Some(Json::string("log")) ||
512	      kind == Some(Json::string("error")) else {
513	      self.remember_unrecognized_json(event)
514	      return
515	    }
516	    let message = match field(event, "msg") {
517	      Some(value) => Some(value)
518	      None =>
519	        match field(event, "message") {
520	          Some(value) => Some(value)
521	          None =>
522	            match field(event, "error") {
523	              Some(Json::Object(_) as value) => field(value, "message")
524	              value => value
525	            }
526	        }
527	    }
528	    guard message is Some(Json::String(text)) else {
529	      self.remember_unrecognized_json(event)
530	      return
531	    }
532	    let level = field(event, "level")
533	    self.message(
534	      text,
535	      debug=level == Some(Json::string("debug")) ||
536	        level == Some(Json::string("trace")),
537	      warning=kind == Some(Json::string("error")) ||
538	        level == Some(Json::string("warn")) ||
539	        level == Some(Json::string("error")),
540	      emit=messages || (statuses && kind != None),
541	    )
542	  } else {
543	    if event != Json::null() {
544	      self.remember_unrecognized_json(event)
545	      return
546	    }
547	    // Malformed JSON and binary output are not a safe free-text fallback.
548	    let text = line.trim().to_owned()
549	    if text.has_prefix("[ERROR]") || text.has_prefix("[WARN]") {
550	      self.message(text, debug=false, warning=true, emit=messages)
551	      return
552	    }
553	    if text.has_prefix("{") || text.has_prefix("[") {
554	      self.details_truncated = true
555	      self.remember_unrecognized(text)
556	      return
557	    }
558	    self.message(
559	      text,
560	      debug=text.contains(" DEBUG ") ||
561	        text.contains(" TRACE ") ||
562	        text.has_prefix("DEBUG ") ||
563	        text.has_prefix("TRACE "),
564	      warning=text.contains(" WARN ") ||
565	        text.contains(" ERROR ") ||
566	        text.has_prefix("WARN ") ||
567	        text.has_prefix("ERROR "),
568	      emit=messages,
569	    )
570	  }
571	}
