573	///|
574	async fn Progress::stderr_line(
575	  self : Progress,
576	  line : String,
577	  statuses~ : Bool,
578	  messages~ : Bool,
579	) -> Unit {
580	  let event = @json.parse(line) catch { _ => Json::null() }
581	  if event != Json::null() {
582	    self.line(line, statuses~, messages~)
583	    let truncated : Ref[Bool] = { val: false, }
584	    let safe = diagnostic_json(event, {}, self.secrets, truncated, 0).stringify()
585	    if truncated.val {
586	      self.details_truncated = true
587	    }
588	    self.message(safe, debug=false, warning=true, emit=false)
589	    return
590	  } else if event == Json::null() &&
591	    (line.trim().has_prefix("[") || line.trim().has_prefix("{")) {
592	    self.details_truncated = true
593	    self.message(line, debug=false, warning=true, emit=false)
594	    return
595	  }
596	  self.line(line, statuses~, messages~)
597	}
