599	///|
600	async fn Progress::read_output(
601	  self : Progress,
602	  reader : @process.ReadFromProcess,
603	  capture~ : Bool,
604	  statuses~ : Bool = false,
605	  messages~ : Bool = false,
606	  raw_messages~ : Bool = false,
607	) -> String {
608	  let output = @buffer.Buffer(size_hint=4096)
609	  let pending = @buffer.Buffer(size_hint=4096)
610	  let mut oversized = false
611	  let mut tail = ""
612	  while reader.read_some(max_len=4096) is Some(chunk) {
613	    if capture {
614	      output.write_bytes(chunk)
615	    } else {
616	      tail += @utf8.decode_lossy(chunk)
617	      if tail.length() > 8192 {
618	        tail = tail[tail.length() - 8192:].to_owned()
619	      }
620	    }
621	    for byte in chunk {
622	      if byte == b'\n' || byte == b'\r' {
623	        if !oversized && pending.length() > 0 {
624	          let line = @utf8.decode(pending.to_bytes()) catch {
625	            _ => {
626	              self.details_truncated = true
627	              ""
628	            }
629	          }
630	          if raw_messages {
631	            self.message(line, debug=false, warning=true, emit=false)
632	          } else if capture {
633	            self.line(line, statuses~, messages~)
634	          } else {
635	            self.stderr_line(line, statuses~, messages~)
636	          }
637	        }
638	        pending.reset()
639	        oversized = false
640	      } else if !oversized {
641	        if pending.length() == 65536 {
642	          pending.reset()
643	          oversized = true
644	          self.details_truncated = true
645	        } else {
646	          pending.write_byte(byte)
647	        }
648	      }
649	    }
650	  }
651	  if !oversized && pending.length() > 0 {
652	    let line = @utf8.decode(pending.to_bytes()) catch {
653	      _ => {
654	        self.details_truncated = true
655	        ""
656	      }
657	    }
658	    let masked = diagnostic_partial_secret(line, self.secrets)
659	    if masked != line {
660	      self.details_truncated = true
661	    }
662	    if raw_messages {
663	      self.message(masked, debug=false, warning=true, emit=false)
664	    } else if capture {
665	      self.line(masked, statuses~, messages~)
666	    } else {
667	      self.stderr_line(masked, statuses~, messages~)
668	    }
669	  }
670	  if capture {
671	    @utf8.decode(output.to_bytes())
672	  } else {
673	    tail
674	  }
675	}

