129	async fn wait_ssh_proxy(state : Json, role : String) -> Unit {
130	  let path = required(state, "socketDirectory") + "/" + role + "-proxy.lock"
131	  if !@fs.exists(path) {
132	    return
133	  }
134	  let canonical = @fs.realpath(path)
135	  let lock = @fs.open(path, mode=ReadWrite)
136	  defer lock.close()
137	  @async.with_timeout(5000, async fn() {
138	    while !lock.try_lock(Exclusive) {
139	      @async.sleep(25)
140	    }
141	    let pending = owned_transports(adapter_state_home(), canonical)
142	    if !pending.is_empty() {
143	      if !supervisor_alive(adapter_state_home()) {
144	        ensure_supervisor()
145	      }
146	      wait_transport_cleanup(pending)
147	    }
148	  })
149	}
