151	///|
152	async fn owned_transports(root : String, lease : String) -> Array[String] {
153	  let base = root + "/transports"
154	  let pending = []
155	  if !@fs.exists(base) {
156	    return pending
157	  }
158	  for name in @fs.readdir(base) {
159	    let directory = base + "/" + name
160	    let receipt = directory + "/state.json"
161	    let owned = try
162	      field(@json.parse(@fs.read_file(receipt).text()), "lease") ==
163	      Some(Json::string(lease))
164	    catch {
165	      error => if !@fs.exists(receipt) { false } else { raise error }
166	    }
167	    if owned {
168	      pending.push(directory)
169	    }
170	  }
171	  pending
172	}
