174	///|
175	async fn wait_transport_cleanup(pending : Array[String]) -> Unit {
176	  for directory in pending {
177	    while @fs.exists(directory) && !@fs.exists(directory + "/done") {
178	      @async.sleep(25)
179	    }
180	  }
181	}

