386	fn Progress::safe_message(self : Progress, text : String) -> String? {
387	  guard terminal_text(text) is Some(text) else { return None }
388	  let chars = text.iter().to_array()
389	  if chars.is_empty() {
390	    return Some("")
391	  }
392	  let output = @buffer.Buffer(size_hint=text.length())
393	  let mut position = 0
394	  while position < chars.length() {
395	    if self.private_key {
396	      if private_key_marker(chars, position, false) is Some((_, end)) {
397	        self.private_key = false
398	        position = end
399	      } else {
400	        self.details_truncated = true
401	        position = chars.length()
402	      }
403	    } else if private_key_marker(chars, position, true) is Some((start, end)) {
404	      output.write_string_utf8(character_text(chars, position, start))
405	      output.write_string_utf8("[private key redacted]")
406	      self.private_key = true
407	      position = end
408	      if private_key_marker(chars, position, false) is None {
